(function(){
  if (typeof window.SockJS !== 'undefined') return;
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/sockjs-client@1/dist/sockjs.min.js';
  s.onload = function(){ console.info('SockJS loaded'); };
  s.onerror = function(){ console.warn('Failed to load SockJS from CDN'); };
  document.head.appendChild(s);
})();

